/** Injected by vite.config.ts at build time. */
declare const __APP_VERSION__: string;
/** True in the dev server and the test builds (`--mode e2e`, `--mode crashtest`); the literal false in a production build. */
declare const __TEST_HOOKS__: boolean;
/** True only in the dev server and the crash-test build (vite.config.ts); the literal false in a production build. */
declare const __CRASH_HOOKS__: boolean;
/** Short Git commit of the build (or "dev"). */
declare const __BUILD_ID__: string;
